// ===== @ingroup meos_geo_tile =====
static void Gen_stbox_get_time_tile(DataChunk &args, ExpressionState &, Vector &result) {
    EnsureMeosThreadInitialized();
    const idx_t rows = args.size();
    for (idx_t c = 0; c < 3; c++) args.data[c].Flatten(rows);
    auto in0 = FlatVector::GetData<timestamp_tz_t>(args.data[0]);
    auto in1 = FlatVector::GetData<interval_t>(args.data[1]);
    auto in2 = FlatVector::GetData<timestamp_tz_t>(args.data[2]);
    auto out = FlatVector::GetData<string_t>(result);
    auto &outv = FlatVector::Validity(result);
    for (idx_t i = 0; i < rows; i++) {
        bool valid = true;
        for (idx_t c = 0; c < 3; c++)
            if (!FlatVector::Validity(args.data[c]).RowIsValid(i)) { valid = false; break; }
        if (!valid) { outv.SetInvalid(i); continue; }
        STBox *r = stbox_get_time_tile(DuckDBToMeosTimestamp(in0[i]).value, MeosIntervalArg(in1[i]), DuckDBToMeosTimestamp(in2[i]).value);
        if (!r) { outv.SetInvalid(i); continue; }
        out[i] = StboxToBlob(result, r);
    }
}

static void Gen_stbox_get_time_tile_a2(DataChunk &args, ExpressionState &, Vector &result) {
    EnsureMeosThreadInitialized();
    const idx_t rows = args.size();
    for (idx_t c = 0; c < 2; c++) args.data[c].Flatten(rows);
    auto in0 = FlatVector::GetData<timestamp_tz_t>(args.data[0]);
    auto in1 = FlatVector::GetData<interval_t>(args.data[1]);
    auto out = FlatVector::GetData<string_t>(result);
    auto &outv = FlatVector::Validity(result);
    for (idx_t i = 0; i < rows; i++) {
        bool valid = true;
        for (idx_t c = 0; c < 2; c++)
            if (!FlatVector::Validity(args.data[c]).RowIsValid(i)) { valid = false; break; }
        if (!valid) { outv.SetInvalid(i); continue; }
        STBox *r = stbox_get_time_tile(DuckDBToMeosTimestamp(in0[i]).value, MeosIntervalArg(in1[i]), timestamptz_in("2000-01-03", -1));
        if (!r) { outv.SetInvalid(i); continue; }
        out[i] = StboxToBlob(result, r);
    }
}


